<details class="cr-panel cr-disclosure"><summary><x-icon name="calendar"/>Historial de turnos de la sede <span>{{ $shifts->count() }} registros</span></summary><div class="cr-table-scroll"><table class="cr-table"><thead><tr><th>Turno</th><th>Responsable</th><th>Apertura / cierre</th><th>Fondo inicial</th><th>Efectivo esperado</th><th>Contado</th><th>Diferencia</th><th>Estado</th></tr></thead><tbody>@forelse($shifts as $record)<tr><td>#{{ $record->id_turno_caja }}</td><td>{{ trim($record->cajero_nombre.' '.$record->cajero_apellido) }}</td><td>{{ $date($record->abierta_at) }}<small>{{ $date($record->cerrada_at) }}</small></td><td>{{ $money($record->fondo_inicial) }}</td><td>{{ $record->efectivo_esperado===null?'Pendiente':$money($record->efectivo_esperado) }}</td><td>{{ $record->efectivo_contado===null?'Pendiente':$money($record->efectivo_contado) }}</td><td><span class="cr-badge cr-{{ $record->diferencia===null?'gray':((float)$record->diferencia==0?'green':'red') }}">{{ $record->diferencia===null?'Pendiente':$money($record->diferencia) }}</span></td><td><span class="cr-badge cr-{{ $record->estado==='abierto'?'green':'gray' }}">{{ ucfirst($record->estado) }}</span></td></tr>@empty<tr><td colspan="8" class="cr-empty">Todavía no hay turnos registrados.</td></tr>@endforelse</tbody></table></div></details>
